import {installationScopes,installationContext,requestDevicePort,candidateInfo} from './device-connection.js';
import {escapeHTML as esc} from './operations-ui.js';
const label=d=>d.role==='controller'?'Intersection coordinator':d.placement==='downstream'?'Exit counter':`${d.offset_m} m upstream puck`;
const usbIcon=`<svg viewBox="0 0 48 64" fill="none" aria-hidden="true"><rect x="13" y="1" width="22" height="15" rx="2" stroke="currentColor" stroke-width="2"/><path d="M19 1v6m10-6v6M10 16h28v24a8 8 0 0 1-8 8h-4v15h-4V48h-4a8 8 0 0 1-8-8V16Z" stroke="currentColor" stroke-width="2"/><path d="M24 22v18m0-7-6-4m6 0 6-5" stroke="currentColor" stroke-width="2"/></svg>`;
export function deviceInstallerHTML(){return `<div class="title-row"><div><span class="eyebrow">INSTALLATION / DEVICES</span><h1>Connect a device.</h1><p class="subtitle">Choose a planned component, then select its USB device in your browser.</p></div><button class="button" id="device-back">← Area planner</button></div><div id="device-workbench" class="device-workbench"></div>`;}
export class DeviceInstaller{
 constructor({project,siteId,state={},onBack,onDownload,readOnly=false}){Object.assign(this,{project,state,onBack,onDownload,readOnly});const scopes=installationScopes(project);this.siteId=scopes.some(s=>s.id===(siteId||state.siteId))?(siteId||state.siteId):scopes[0].id;this.deviceId=state.deviceId;this.abort=new AbortController();this.port=null;this.info=null;this.message='';this.choosing=false;}
 mount(){this.root=document.querySelector('#device-workbench');document.querySelector('#device-back').addEventListener('click',()=>this.onBack(),{signal:this.abort.signal});this.root.addEventListener('click',e=>{const b=e.target.closest('[data-connect-action]');if(b)this.action(b.dataset.connectAction);},{signal:this.abort.signal});this.root.addEventListener('change',e=>{if(e.target.id==='connect-site'){this.siteId=e.target.value;this.deviceId=null;this.clear();this.render();}},{signal:this.abort.signal});navigator.serial?.addEventListener('disconnect',e=>{if((e.port||e.target)===this.port){this.clear();this.message='Device unplugged. Connect it again when ready.';this.render();}},{signal:this.abort.signal});this.render();}
 clear(){this.port=null;this.info=null;this.message='';}
 render(){if(this.destroyed)return;this.context=installationContext(this.project,this.siteId);const c=this.context;if(!c.devices.some(d=>d.id===this.deviceId))this.deviceId=c.devices.find(d=>d.role==='sensor')?.id||c.devices[0].id;this.state.siteId=this.siteId;this.state.deviceId=this.deviceId;const d=c.devices.find(d=>d.id===this.deviceId),lane=c.site.lanes.find(l=>l.id===d.lane_id),profile=c.profileFor(d.id),locked=this.choosing||this.readOnly;
 this.root.innerHTML=`<section class="panel connect-inventory"><div class="panel-head"><h2>Planned components</h2><span class="count-pill">${c.devices.length}</span></div><div class="panel-body"><label class="field">Intersection<select id="connect-site" ${locked?'disabled':''}>${installationScopes(this.project).map(s=>`<option value="${esc(s.id)}" ${s.id===this.siteId?'selected':''}>${esc(s.name)} · ${s.kind}</option>`).join('')}</select></label><p class="hint">${c.devices.filter(x=>x.role==='sensor').length} pucks · 1 coordinator</p><div class="connect-device-list" aria-label="Planned components">${c.devices.map(x=>`<button data-connect-action="select:${esc(x.id)}" class="${x.id===d.id?'selected':''}" aria-pressed="${x.id===d.id}" ${locked?'disabled':''}><span class="connect-symbol">${x.role==='controller'?'△':x.placement==='downstream'?'◉':'●'}</span><span><strong>${esc(label(x))}</strong><small>${esc(x.id)}</small></span></button>`).join('')}</div></div></section><section class="panel connect-panel"><div class="panel-head"><h2>${esc(label(d))}</h2><span class="badge ${this.info?'blue':'gray'}">${this.info?'DEVICE SELECTED':'AWAITING USB'}</span></div><div class="panel-body"><div class="connect-target"><span class="eyebrow">SELECTED PLANNING ID</span><h3>${esc(d.id)}</h3><p>${esc(lane?.road_name||c.site.name)}${lane?` · lane ${lane.lane_number}`:''}</p></div><div class="connect-prompt"><div class="connect-usb-icon">${usbIcon}</div><h2>${this.info?'USB device selected':'Plug in your device.'}</h2><p>${this.info?'The USB interface is available. Board and firmware compatibility have not been verified.':'Use a data USB cable. The browser’s device chooser will list matching connected devices.'}</p><button class="button dark" data-connect-action="choose" ${locked?'disabled':''}>${this.choosing?'Opening device chooser…':this.info?'Choose another device':'Connect device'}</button>${this.info?`<div class="connect-usb-info"><strong>Espressif USB serial</strong><span>VID ${this.info.usbVendorId.toString(16).toUpperCase().padStart(4,'0')}${Number.isInteger(this.info.usbProductId)?` · PID ${this.info.usbProductId.toString(16).toUpperCase().padStart(4,'0')}`:''}</span></div><button class="subtle-link" data-connect-action="clear">Clear selection</button>`:''}<p class="connect-feedback" role="status">${esc(this.message||'No compatible device selected.')}</p></div><div class="connect-footer"><span>${d.role==='controller'&&!profile.location?'Cabinet position is unlocated.':profile.location?`Planned position · ${profile.location.latitude.toFixed(7)}, ${profile.location.longitude.toFixed(7)}`:'Planning profile'}</span><button class="subtle-link" data-connect-action="profile">Download device profile ↗</button></div><details class="connect-help"><summary>Connection help</summary><p>Use desktop Chrome or Edge on HTTPS. If the list is empty, check the USB data cable and board connection. For the P1 puck, remove JP101 before USB-powered programming.</p><p>This screen selects a USB interface. Firmware flashing and configuration writes will be enabled when a compatible firmware package is supplied. Nothing is written to the board here.</p></details></div></section>`;}
 async action(action){if(this.choosing||this.readOnly)return;if(action.startsWith('select:')){this.deviceId=action.slice(7);this.clear();this.render();return;}if(action==='profile'){this.onDownload(`${this.deviceId}.json`,this.context.profileFor(this.deviceId));return;}if(action==='clear'){this.clear();this.render();return;}if(action!=='choose')return;
 try{this.choosing=true;const pending=requestDevicePort(navigator.serial);this.render();const port=await pending;if(this.destroyed)return;this.info=candidateInfo(port);this.port=port;this.message='Device selected. No firmware or configuration has been written.';}catch(e){this.clear();this.message=e.name==='NotFoundError'?'No device selected. Plug in the board and try again.':e.message;}finally{this.choosing=false;this.render();}}
 destroy(){this.destroyed=true;this.abort.abort();this.clear();}
}
